struct Match{u32 index;u8 variant;};static bool find_rec(usize size,const u8 d[32],Match&m){for(u32 i=0;i<kReceiverCount;++i){const ReceiverRec&r=kReceivers[i];if(r.size!=size)continue;if(eq(r.stock_sha,d,32)){m={i,0};return true;}if(nonzero(r.a1_sha)&&eq(r.a1_sha,d,32)){m={i,1};return true;}}return false;}
static const u32 PMAP=4096u;struct Pipe{volatile u64 h;u32 rec;u8 variant;u8 pad[3];};static Pipe g_pm[PMAP]={};static volatile u32 g_logged[kReceiverCount]={};
