static char hx(u32 v){v&=15;return(char)(v<10?'0'+v:'A'+v-10);}static char*ps(char*d,const char*s){while(*s)*d++=*s++;return d;}static char*ph32(char*d,u32 v){for(int i=7;i>=0;--i)*d++=hx(v>>(i*4));return d;}static char*ph16(char*d,u32 v){for(int i=3;i>=0;--i)*d++=hx(v>>(i*4));return d;}static char*ph8(char*d,const u8*s){for(u32 i=0;i<8;++i){*d++=hx(s[i]>>4);*d++=hx(s[i]);}return d;}
